package bookstore

func Cost(books []int) int {
	var counts [5]int
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}

	// price of a group of size k (in cents)
	price := [6]int{0, 800, 1520, 2160, 2560, 3000}

	// Build the layers: layer k contains the titles that have at least k copies.
	// The number of books in layer k is the number of titles with count >= k.
	total := 0
	fiveGroups := 0
	threeGroups := 0
	for k := 1; ; k++ {
		layer := 0
		for _, c := range counts {
			if c >= k {
				layer++
			}
		}
		if layer == 0 {
			break
		}
		total += price[layer]
		if layer == 5 {
			fiveGroups++
		} else if layer == 3 {
			threeGroups++
		}
	}

	// A 5-layer followed by a 3-layer is cheaper as two 4-groups.
	conversions := fiveGroups
	if threeGroups < fiveGroups {
		conversions = threeGroups
	}
	total -= 40 * conversions
	return total
}
```

