package bookstore

// Cost returns the cheapest total price (in cents) for the given basket of
// books. Each book title is 1-5 and costs 800 cents, with discounts applied
// per group of distinct titles:
//
//	1 book:  0%  ->  800
//	2 books:  5%  -> 1520
//	3 books: 10%  -> 2160
//	4 books: 20%  -> 2560
//	5 books: 25%  -> 3000
//
// The basket is split into groups of distinct titles to maximise the discount.
func Cost(books []int) int {
	var counts [5]int
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}

	// price[k] is the cost of a group of k distinct titles.
	price := [6]int{0, 800, 1520, 2160, 2560, 3000}

	// View the basket as layers: layer k holds one copy of every title that
	// has at least k copies. Layer k therefore contains as many books as there
	// are titles with count >= k.
	total := 0
	fiveGroups := 0
	threeGroups := 0
	for k := 1; k <= maxCount(counts); k++ {
		layer := 0
		for _, c := range counts {
			if c >= k {
				layer++
			}
		}
		total += price[layer]
		switch layer {
		case 5:
			fiveGroups++
		case 3:
			threeGroups++
		}
	}

	// A group of 5 plus a group of 3 costs 3000+2160 = 5160, but the same eight
	// books as two groups of 4 cost 2*2560 = 5120. Pair up as many 5-layers
	// with 3-layers as possible to save 40 per pair.
	conversions := fiveGroups
	if threeGroups < conversions {
		conversions = threeGroups
	}
	total -= 40 * conversions
	return total
}

func maxCount(counts [5]int) int {
	m := 0
	for _, c := range counts {
		if c > m {
			m = c
		}
	}
	return m
}
